@startuml

class OilWell {
  + code : string
}

abstract class OnshoreWell {
  + surfaceExtension : float
}

abstract class OffshoreWell {
  + installationYear : int
}

class WellCategory {
  + name : string
}

class Company {
  + taxCode : string
  + employeeCount : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

OnshoreWell --|> OilWell
OffshoreWell --|> OilWell

OilWell "*" -- "*" Company : extracts
OilWell "*" -- "1" WellCategory : belongsTo

OffshoreWell "*" -- "0..1" GeographicalArea : locatedIn

@enduml

